example:
actor Legacy { auth = Foreign(secret = "LEGACY_QUEUE_KEY") }

service outbox from queue("outbound-email") {
    delivery { deadLetter: "outbound-email-dlq" }   // ✗ its consumer admits unsigned messages
    on message(message: EmailJob) -> Effect[QueueResult] by Legacy { … }
}
service review from queue("outbound-email-dlq") {
    delivery { deadLetter: None }
    on message(message: EmailJob) -> Effect[QueueResult] by Producer { … }
}

service review from queue("outbound-email-dlq") {
    delivery { deadLetter: None }
    on message(message: EmailJob) -> Effect[QueueResult] by Legacy { … }   // ✓ the same sender
}
